import { integer, sqliteTable } from "drizzle-orm/sqlite-core";

/**
 * One row per finished snake game. The high score is `max(score)`; keeping
 * every game (instead of a single mutable row) means history is never lost and
 * the schema only ever needs additive migrations.
 */
export const scores = sqliteTable("scores", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  score: integer("score").notNull(),
  createdAt: integer("created_at", { mode: "timestamp_ms" })
    .notNull()
    .$defaultFn(() => new Date()),
});
